 public void ApplyOptions(Settings options){if(ArchiveView!=null){ArchiveView.Dispose();ArchiveView=null;}var previousKey=HistoryKey;var previousMetrics=last;cardsDevice=null;config=options;if(TerminalView!=null)TerminalView.ApplyOptions(config.Terminal);ArchiveRepository.Days=config.RetentionDays;ArchiveRepository.LimitMB=config.ArchiveLimitMB;Theme.Apply(config.ThemeName);Resources=Theme.Resources();RefreshPickerTemplate();requestVersion++;Populate();if(testMode&&previousKey==HistoryKey&&previousMetrics!=null){last=previousMetrics;RenderView();SetMetrics(previousMetrics,false);}if(tray!=null&&tray.ContextMenuStrip!=null){tray.ContextMenuStrip.BackColor=TrayColors.Convert(Theme.Surface);tray.ContextMenuStrip.ForeColor=TrayColors.Convert(Theme.Ink);foreach(Forms.ToolStripItem item in tray.ContextMenuStrip.Items)item.ForeColor=TrayColors.Convert(Theme.Ink);}DarkTitle();RefreshDeviceRail();RefreshWorkspaceTheme();if(Workspace!=null)Workspace.SetDevices(config.Servers,active);if(FileView!=null&&active!=null)FileView.SetServer(active);if(CompactView!=null)CompactView.RefreshAppearance();PaneLayouts.RefreshTree(Root);}
 void OpenSettings(){var editor=new SettingsWindow(config.Copy(),testMode){Owner=this};editor.ApplyRequested+=(options,startup)=>{if(!testMode){Startup.Set(startup);Storage.Save(options);}ApplyOptions(options.Copy());};editor.ShowDialog();}
 void InitTray(){tray=new Forms.NotifyIcon();RefreshTrayIcon();SystemEvents.UserPreferenceChanged+=OnTrayThemeChanged;tray.Text="AQ Server · 资源监控";tray.MouseUp+=(sender,e)=>{if(e.Button==Forms.MouseButtons.Right)Dispatcher.BeginInvoke((Action)ShowTrayFlyout);};tray.DoubleClick+=(sender,e)=>Dispatcher.BeginInvoke((Action)Restore);tray.Visible=true;}
 public bool SilentTrayTransitions; public void HideToTray(){if(CompactView!=null)CompactView.Hide();Hide();if(tray!=null&&!balloonShown&&!SilentTrayTransitions){balloonShown=true;tray.ShowBalloonTip(3000,"AQ Server 已在后台运行","双击托盘图标可恢复窗口，右键可退出或设置开机自启。",Forms.ToolTipIcon.Info);}}
