 public void ShowCompact(){if(CompactView==null){CompactView=new CompactWindow(this);if(testMode||SilentTrayTransitions){CompactView.ShowActivated=false;CompactView.Left=-18000;CompactView.Top=-18000;}}CompactView.RefreshDevices();CompactView.Update(CompactMetrics,CompactTimestamp);CompactView.Show();Hide();if(!testMode&&!SilentTrayTransitions)CompactView.Activate();}
 public void Restore(){if(exitAllowed||Dispatcher.HasShutdownStarted)return;if(CompactView!=null)CompactView.Hide();Show();WindowState=WindowState.Normal;Activate();}
 public void Exit(){exitAllowed=true;if(trayFlyout!=null)trayFlyout.Close();if(TerminalView!=null){TerminalView.Dispose();TerminalView=null;}if(FileView!=null){FileView.Dispose();FileView=null;}if(CompactView!=null){CompactView.End();CompactView=null;}timer.Stop();if(capture!=null){capture.Dispose();capture=null;}if(!testMode)try{Storage.Save(config);}catch{}if(ArchiveView!=null)ArchiveView.Dispose();if(archiveWriter!=null){archiveWriter.Dispose();archiveWriter=null;}if(tray!=null){SystemEvents.UserPreferenceChanged-=OnTrayThemeChanged;tray.Visible=false;tray.Dispose();tray=null;if(trayIcon!=null){trayIcon.Dispose();trayIcon=null;}}Close();if(!testMode)Application.Current.Shutdown();}
 public string NativeReview(){UpdateLayout();double gap=View!="GPU"||CardViews.Count==0?double.NaN:CardViews.Min(card=>Bounds(card.Meter,card).Top-Bounds(card.Percent,card).Bottom);var source=PresentationSource.FromVisual(this);double scale=source==null?1:source.CompositionTarget.TransformToDevice.M11;return "NATIVE_DPI="+(96*scale).ToString(CultureInfo.InvariantCulture)+"\nGPU_CARDS="+CardViews.Count+"\nMIN_PERCENT_METER_GAP_DIP="+(double.IsNaN(gap)?"N/A (GPU page hidden)":gap.ToString(CultureInfo.InvariantCulture))+"\nLAYOUT_ERRORS="+Audit().Count+"\nCHINESE_FONT="+FontFamily.Source+"\n";}
 public bool TrayVisible{get{return tray!=null&&tray.Visible;}}
