 public void RenderImage(string path,int width,int height,int dpi){Snapshot.Save(Root,path,width,height,dpi,Reflow);}
 public List<string> Audit(){var errors=new List<string>();foreach(var card in (View=="GPU"?CardViews:new List<GpuCard>())){var id=Bounds(card.Id,card);var name=Bounds(card.Model,card);var percent=Bounds(card.Percent,card);var meter=Bounds(card.Meter,card);if(name.Top-id.Bottom<5)errors.Add("GPU title/model gap <5");if(meter.Top-percent.Bottom<10)errors.Add("GPU percent/meter gap <10");if(card.Model.ActualHeight+0.1<card.Model.DesiredSize.Height-card.Model.Margin.Top-card.Model.Margin.Bottom)errors.Add("GPU model clipped vertically actual="+card.Model.ActualHeight+" desired="+card.Model.DesiredSize.Height+" margin="+card.Model.Margin.Top+","+card.Model.Margin.Bottom);foreach(var row in new[]{card.MemoryRow,card.TemperatureRow,card.PowerRow}){var l=(TextBlock)row.Children[0];var v=(TextBlock)row.Children[1];if(Bounds(l,row).Right+8>Bounds(v,row).Left)errors.Add("metric columns overlap");}if(card.DesiredSize.Width>card.ActualWidth+17)errors.Add("card horizontal overflow");}
 var t=Bounds(TerminalButton,Root);var s=Bounds(SettingsButton,Root);if(Math.Abs(t.Top-s.Top)>0.5||Math.Abs(t.Height-s.Height)>0.5)errors.Add("toolbar buttons misaligned");if(CompactButton!=null){var c=Bounds(CompactButton,Root);if(Math.Abs(c.Top-s.Top)>0.5||Math.Abs(c.Height-s.Height)>0.5)errors.Add("compact toolbar misaligned");if(c.Right>Root.ActualWidth+1)errors.Add("toolbar overflows");}if(Scroll.ExtentWidth>Scroll.ViewportWidth+1)errors.Add("horizontal scrolling required");return errors;}
 static Rect Bounds(FrameworkElement e,Visual parent){return e.TransformToAncestor(parent).TransformBounds(new Rect(0,0,e.ActualWidth,e.ActualHeight));}
